use std::process::ExitCode;

use callisto_graph::apply::{apply_version_plan, ApplyOptions, ApplyOutcome};
use callisto_graph::commands::VersionOptions;
use callisto_graph::resolver::ManifestWalkResolver;
use callisto_graph::GraphError;
use callisto_model::vcs::VERSION_CHECKPOINT;
use callisto_model::{ApplyPermit, DiagnosticSeverity};

use crate::cli::{GlobalArgs, OutputFormat, VersionArgs};
use crate::commands::release::workspace_decision_path;
use crate::error::CliError;
use crate::output::{emit_line, emit_report};
use crate::render;
use crate::runner::CliCommandRunner;
use crate::workspace::{load_workspace, select_inference};

/// A throwaway worktree of the checkpoint, removed when dropped so no exit path leaves one registered.
struct ResumeTree<'g, 'r> {
    git: &'g callisto_model::vcs::GitAccess<'r>,
    tree: std::path::PathBuf,
    _dir: tempfile::TempDir,
}

impl Drop for ResumeTree<'_, '_> {
    fn drop(&mut self) {
        self.git.remove_worktree(&self.tree).ok();
    }
}

/// Checks the checkpoint out in a throwaway worktree and loads the workspace there.
fn open_checkpoint_tree<'g, 'r>(
    git: &'g callisto_model::vcs::GitAccess<'r>,
    checkpoint: &callisto_model::vcs::Checkpoint,
    runner: &'r CliCommandRunner,
    global: &GlobalArgs,
) -> Result<
    (
        ResumeTree<'g, 'r>,
        callisto_graph::Workspace<'r, CliCommandRunner, ManifestWalkResolver>,
    ),
    CliError,
> {
    let dir = tempfile::tempdir().map_err(|source| CliError::Io { source, path: None })?;
    let tree = dir.path().join("tree");
    git.add_checkpoint_worktree(VERSION_CHECKPOINT, &tree, &checkpoint.facts.head)
        .map_err(GraphError::from)?;
    let resume = ResumeTree { git, tree, _dir: dir };
    let prefix = git.root_prefix().map_err(GraphError::from)?;
    let scratch = load_workspace(
        &GlobalArgs {
            cwd: resume.tree.join(prefix),
            ..global.clone()
        },
        runner,
    )?;
    Ok((resume, scratch))
}

/// `version --abort`: discards an interrupted run. Files the run wrote that still hold its output are put back as the
/// checkpoint recorded them, files it created are removed, and a file edited since is left and reported, which keeps
/// the checkpoint so the abort can be repeated. If `HEAD` moved, the run may have been committed by hand, so no file is
/// touched and only the checkpoint is dropped.
fn abort(global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let runner = CliCommandRunner;
    let ws = load_workspace(global, &runner)?;
    let git = ws.git_access();
    let Some(checkpoint) = git.checkpoint(VERSION_CHECKPOINT).map_err(GraphError::from)? else {
        emit_line("No interrupted `version` run to discard.")?;
        return Ok(ExitCode::SUCCESS);
    };
    let facts = git
        .checkpoint_facts(env!("CARGO_PKG_VERSION"))
        .map_err(GraphError::from)?;
    if facts.head != checkpoint.facts.head {
        git.delete_checkpoint(VERSION_CHECKPOINT).map_err(GraphError::from)?;
        emit_line("`HEAD` moved since the interrupted run, so its files were left as they are. Checkpoint removed.")?;
        return Ok(ExitCode::SUCCESS);
    }
    let permit =
        ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::VersionEmitDryRun { flag: "abort" })?;
    let (tree, scratch) = open_checkpoint_tree(git, &checkpoint, &runner, global)?;
    let opts = VersionOptions {
        strict: false,
        allow_empty_changesets: true,
    };
    let date = if checkpoint.date.is_empty() {
        today_utc()
    } else {
        checkpoint.date.clone()
    };
    let plan = callisto_graph::commands::plan_version_dated(&scratch, &select_inference(), &opts, Some(&date))?;
    let analysis =
        callisto_graph::commands::analyze_resume(&ws, &scratch, &checkpoint, &facts, &plan, &runner, &permit)?;
    drop(scratch);
    drop(tree);

    for path in &analysis.restore {
        git.restore_path(VERSION_CHECKPOINT, path).map_err(GraphError::from)?;
    }
    for path in &analysis.remove {
        git.discard_created(path).map_err(GraphError::from)?;
    }
    if !analysis.edited.is_empty() {
        let edited = analysis.edited.iter().map(|p| p.display().to_string()).collect();
        return Err(GraphError::CheckpointAbortIncomplete { edited }.into());
    }
    git.delete_checkpoint(VERSION_CHECKPOINT).map_err(GraphError::from)?;
    emit_line("Discarded the interrupted `version` run.")?;
    Ok(ExitCode::SUCCESS)
}

pub fn handle(args: VersionArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    if args.abort {
        // Fails before loading anything when `--dry-run` is also given, as for the emitted files.
        if global.dry_run {
            return Err(CliError::VersionEmitDryRun { flag: "abort" });
        }
        return abort(global);
    }
    if global.dry_run {
        for (flag, set) in [
            ("emit-decision", args.emit_decision.is_some()),
            ("emit-preview", args.emit_preview.is_some()),
        ] {
            if set {
                return Err(CliError::VersionEmitDryRun { flag });
            }
        }
    }

    let runner = CliCommandRunner;
    let ws = load_workspace(global, &runner)?;

    let inference = select_inference();
    let opts = VersionOptions {
        strict: args.strict,
        allow_empty_changesets: args.allow_empty_changesets,
    };

    // An interrupted run left its inputs at the checkpoint (ADR 13): plan from them, or refuse if they changed.
    // A repository with no commits has nothing to record a checkpoint against.
    let git = ws.git_access();
    let facts = match git.resolve_commit("HEAD").map_err(GraphError::from)? {
        Some(_) => Some(
            git.checkpoint_facts(env!("CARGO_PKG_VERSION"))
                .map_err(GraphError::from)?,
        ),
        None => None,
    };
    let checkpoint = match &facts {
        Some(_) => git.checkpoint(VERSION_CHECKPOINT).map_err(GraphError::from)?,
        None => None,
    };
    let (resume_tree, checkpoint_ws) = match &checkpoint {
        Some(checkpoint) => {
            let (tree, scratch) = open_checkpoint_tree(git, checkpoint, &runner, global)?;
            (Some(tree), Some(scratch))
        }
        None => (None, None),
    };
    let plan_ws = checkpoint_ws.as_ref().unwrap_or(&ws);

    // A resume plans with the date the interrupted run used, so its changelog sections all carry one date.
    let date = match &checkpoint {
        Some(checkpoint) if !checkpoint.date.is_empty() => checkpoint.date.clone(),
        _ => today_utc(),
    };
    let plan = callisto_graph::commands::plan_version_dated(plan_ws, &inference, &opts, Some(&date))?;

    // Without a checkpoint, refuses when disk already shows a bump HEAD lacks while release inputs or staged version
    // state remain. With one, the inputs are checked below, once everything that reads the checkpoint's tree is built.
    if checkpoint.is_none() {
        callisto_graph::commands::check_partial_run(&ws)?;
    }

    // Escalated diagnostics (e.g. --strict on "no pending changesets") must fail before anything is written.
    let has_errors = plan.diagnostics.iter().any(|d| d.severity == DiagnosticSeverity::Error);

    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run);

    // Derived before any write so an invalid plan fails early; written only after apply succeeds.
    let pending_decision = if !has_errors {
        match args.emit_decision.as_deref() {
            Some(path) => {
                let decision = callisto_graph::commands::derive_release_decision(plan_ws, &plan)?;
                // Workspace-root-relative, not cwd-relative, so `git add -A` and a later `--decision` `git show` agree.
                let relative = workspace_decision_path(path, &ws.root)?;
                Some((ws.root.join(relative), decision))
            }
            None => None,
        }
    } else {
        None
    };

    // Built from the plan before apply consumes the changesets it describes.
    let pending_preview = match args.emit_preview.as_deref().filter(|_| !has_errors) {
        Some(path) => Some((
            global.resolve_file_arg(path),
            callisto_graph::release_preview::build_release_preview_in(plan_ws, &plan)?,
        )),
        None => None,
    };

    // A resume must start from the checkpoint plus some of the interrupted run's own writes. The plan is applied in the
    // checkpoint's scratch worktree to learn what a finished run leaves, which takes the run's own permit and writes
    // only there; a dry run has no permit, so it reports the plan without verifying the inputs.
    if let (Some(scratch), Some(checkpoint), Some(facts), Some(permit), false) =
        (&checkpoint_ws, &checkpoint, &facts, permit.as_ref(), has_errors)
    {
        let analysis =
            callisto_graph::commands::analyze_resume(&ws, scratch, checkpoint, facts, &plan, &runner, permit)?;
        if !analysis.changes.is_empty() {
            return Err(GraphError::CheckpointInputsChanged {
                changes: analysis.changes,
            }
            .into());
        }
    }

    // The plan is in memory, so the checkpoint's worktree has done its job.
    drop(checkpoint_ws);
    drop(resume_tree);

    let apply_opts = ApplyOptions {
        refresh_lockfiles: !args.no_refresh_lockfiles,
        transient: false,
    };

    let applying = !has_errors && permit.is_some();
    if let (true, None, Some(facts), Some(permit)) = (applying, &checkpoint, &facts, permit.as_ref()) {
        // A run that cannot start must leave no checkpoint behind, or the fix its error asks for is never honoured.
        callisto_graph::apply::validate_plan(&ws.root, &plan, &apply_opts, permit, &runner)?;
        git.create_checkpoint(VERSION_CHECKPOINT, facts, &date)
            .map_err(GraphError::from)?;
    }

    let outcome = if has_errors {
        ApplyOutcome::default()
    } else {
        match permit.as_ref() {
            Some(permit) => apply_version_plan(&ws.root, &plan, &runner, &apply_opts, permit)?,
            None => ApplyOutcome::default(),
        }
    };

    if let (Some((full_path, decision)), Some(permit)) = (pending_decision.as_ref(), permit.as_ref()) {
        let content = serde_json::to_string_pretty(decision).expect("release decision serializes") + "\n";
        callisto_model::atomic::atomic_write(full_path, &content, permit).map_err(|source| CliError::Io {
            source,
            path: Some(full_path.clone()),
        })?;
    }

    if let (Some((full_path, preview)), Some(permit)) = (pending_preview.as_ref(), permit.as_ref()) {
        let content = serde_json::to_string_pretty(preview).expect("release preview serializes") + "\n";
        callisto_model::atomic::atomic_write(full_path, &content, permit).map_err(|source| CliError::Io {
            source,
            path: Some(full_path.clone()),
        })?;
    }

    // Every effect, the emitted files included, has landed: the run is complete.
    if applying && facts.is_some() {
        git.delete_checkpoint(VERSION_CHECKPOINT).map_err(GraphError::from)?;
    }

    let report = plan.to_report(&ws.report_ids(), outcome.lockfile_refresh_results);

    if global.dry_run && global.format == OutputFormat::Text {
        emit_line("[DRY-RUN] Version Plan Calculated (no files modified):")?;
    }

    match global.format {
        OutputFormat::Json => emit_report(&mut std::io::stdout(), &report, global.dry_run)?,
        OutputFormat::Text => render::render_version(&report, &ws.config, &mut std::io::stdout())?,
    }

    // Mirrors the pattern in status.rs: diagnostics ride in the report so the
    // caller sees full detail before the non-zero exit.
    if has_errors {
        Ok(ExitCode::FAILURE)
    } else {
        Ok(ExitCode::SUCCESS)
    }
}

/// Today's UTC date as `YYYY-MM-DD`.
fn today_utc() -> String {
    let seconds = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_secs());
    utc_date(i64::try_from(seconds / 86_400).unwrap_or(0))
}

/// Howard Hinnant's civil-from-days: the proleptic Gregorian date of a day count since 1970-01-01.
fn utc_date(days: i64) -> String {
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let day_of_era = z - era * 146_097;
    let year_of_era = (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let shifted_month = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * shifted_month + 2) / 5 + 1;
    let month = if shifted_month < 10 {
        shifted_month + 3
    } else {
        shifted_month - 9
    };
    let year = year_of_era + era * 400 + i64::from(month <= 2);
    format!("{year:04}-{month:02}-{day:02}")
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    #[test]
    fn utc_date_matches_known_days() {
        assert_eq!(super::utc_date(0), "1970-01-01");
        assert_eq!(super::utc_date(59), "1970-03-01");
        assert_eq!(super::utc_date(11_016), "2000-02-29");
        assert_eq!(super::utc_date(20_765), "2026-11-08");
    }

    use callisto_graph::commands::{plan_version, VersionOptions};
    use callisto_graph::infer::NoInference;
    use callisto_graph::locate::IgnoreWalkLocator;
    use callisto_graph::Workspace;
    use callisto_model::{CommandError, CommandOutput, CommandRunner, PackageId};

    struct NoopRunner;

    impl CommandRunner for NoopRunner {
        fn run(&self, _program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            Ok(CommandOutput {
                exit_code: Some(0),
                stdout: String::new(),
                stderr: String::new(),
            })
        }
    }

    fn git_init_with_commit(root: &Path) {
        callisto_fixtures::git::init_repo(root);
        std::fs::write(root.join(".gitkeep"), "").unwrap();
        for args in [vec!["add", "."], vec!["commit", "-q", "-m", "init"]] {
            std::process::Command::new("git")
                .args(&args)
                .current_dir(root)
                .output()
                .expect("git must be installed");
        }
    }

    fn run_git(root: &Path, args: &[&str]) {
        let status = std::process::Command::new("git")
            .args(args)
            .current_dir(root)
            .status()
            .expect("git must be installed");
        assert!(status.success(), "git {args:?} failed");
    }

    fn make_fixture(root: &Path) {
        git_init_with_commit(root);

        std::fs::create_dir_all(root.join("pkg-alpha")).unwrap();
        std::fs::write(
            root.join("pkg-alpha/Cargo.toml"),
            "[package]\nname = \"pkg-alpha\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();

        std::fs::create_dir_all(root.join(".changeset")).unwrap();
        std::fs::write(
            root.join(".changeset/bump-alpha.md"),
            "---\n\"pkg-alpha\": minor\n---\n\nAdd a new feature.\n",
        )
        .unwrap();
    }

    /// Spec: the text rendering of a `VersionReport` produced from a workspace
    /// with a pending changeset must include the package name and both the
    /// `from` and `to` version strings. The `render_version` function writes
    /// one line per bump in the format `<name> <from> → <to>`.
    #[test]
    fn version_text_output_includes_package_name_and_versions() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        make_fixture(root);

        let locator = IgnoreWalkLocator::new(root);
        let runner = NoopRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let inference = NoInference;
        let opts = VersionOptions {
            strict: false,
            allow_empty_changesets: true,
        };

        let plan = plan_version(&ws, &inference, &opts).expect("plan_version must succeed");
        let report = plan.to_report(&ws.report_ids(), None);

        // The report must include a bump for pkg-alpha.
        let pkg_alpha = PackageId::parse("cargo/pkg-alpha").unwrap();
        let bump = report
            .bumps
            .iter()
            .find(|b| b.package == pkg_alpha)
            .expect("pkg-alpha must have a planned bump");

        assert_eq!(bump.from.render(), "1.0.0", "from version must be the current version");
        assert_eq!(
            bump.to.render(),
            "1.1.0",
            "to version must be a minor bump (1.0.0 -> 1.1.0)"
        );

        // Render text output and verify it contains the key strings.
        let mut text_out = Vec::new();
        crate::render::render_version(&report, &ws.config, &mut text_out).unwrap();
        let rendered = String::from_utf8(text_out).unwrap();

        assert!(
            rendered.contains("pkg-alpha"),
            "text output must include package name; got:\n{rendered}"
        );
        assert!(
            rendered.contains("1.0.0"),
            "text output must include from version; got:\n{rendered}"
        );
        assert!(
            rendered.contains("1.1.0"),
            "text output must include to version; got:\n{rendered}"
        );
    }

    /// The empty-changeset diagnostic is deliberately
    /// governed by `validation.allow-empty-changesets` even when nobody set
    /// it, so an operator seeing the warning knows which key silences it.
    /// `render_version` must surface that as an attribution line, not just
    /// the bare diagnostic message.
    #[test]
    fn version_text_output_attributes_empty_changeset_diagnostic_to_its_config_key() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git_init_with_commit(root);

        std::fs::create_dir_all(root.join("pkg-alpha")).unwrap();
        std::fs::write(
            root.join("pkg-alpha/Cargo.toml"),
            "[package]\nname = \"pkg-alpha\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();
        // Deliberately no `.changeset` entries, and no `callisto.toml`
        // opt-out: this is exactly the "no named default" case the
        // attribution line exists to explain.

        let locator = IgnoreWalkLocator::new(root);
        let runner = NoopRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let inference = NoInference;
        let opts = VersionOptions {
            strict: false,
            allow_empty_changesets: false,
        };

        let plan = plan_version(&ws, &inference, &opts).expect("plan_version must succeed");
        let report = plan.to_report(&ws.report_ids(), None);

        assert!(
            report
                .diagnostics
                .iter()
                .any(|d| d.governed_by == Some(callisto_model::ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS)),
            "expected the empty-changeset diagnostic to carry governed_by; got: {:?}",
            report.diagnostics
        );

        let mut text_out = Vec::new();
        crate::render::render_version(&report, &ws.config, &mut text_out).unwrap();
        let rendered = String::from_utf8(text_out).unwrap();

        assert!(
            rendered.contains("governed by [validation].allow-empty-changesets = false (default)"),
            "text output must attribute the diagnostic to its config key; got:\n{rendered}"
        );
    }

    /// Spec: the JSON output of `write_document(&report)` for a `VersionReport`
    /// must be valid JSON. It must include the top-level keys `schemaVersion`
    /// and `bumps`. The `diagnostics` key is omitted when empty
    /// (`skip_serializing_if = "Vec::is_empty"`), so its presence is optional.
    /// Each entry in `bumps` must have `package`, `from`, `to`, and `severity`.
    #[test]
    fn version_json_output_is_valid_json_with_expected_structure() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        make_fixture(root);

        let locator = IgnoreWalkLocator::new(root);
        let runner = NoopRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let inference = NoInference;
        let opts = VersionOptions {
            strict: false,
            allow_empty_changesets: true,
        };

        let plan = plan_version(&ws, &inference, &opts).expect("plan_version must succeed");
        let report = plan.to_report(&ws.report_ids(), None);

        // Serialize to JSON via the same function the CLI uses.
        let mut json_out = Vec::new();
        crate::output::write_document(&mut json_out, &report).unwrap();
        let json_str = String::from_utf8(json_out).unwrap();

        // Must be parseable as valid JSON.
        let parsed: serde_json::Value = serde_json::from_str(&json_str).expect("output must be valid JSON");

        // Top-level structure checks: schemaVersion and bumps are always present.
        assert!(
            parsed.get("schemaVersion").is_some(),
            "JSON must have schemaVersion key; got:\n{json_str}"
        );
        assert!(
            parsed.get("bumps").is_some(),
            "JSON must have bumps key; got:\n{json_str}"
        );
        // diagnostics is omitted when empty (skip_serializing_if); if present it
        // must be an array.
        if let Some(diags) = parsed.get("diagnostics") {
            assert!(
                diags.is_array(),
                "diagnostics key must be an array when present; got:\n{json_str}"
            );
        }

        // Each bump must have the required fields.
        let bumps = parsed["bumps"].as_array().expect("bumps must be an array");
        assert!(!bumps.is_empty(), "bumps array must be non-empty for the test fixture");

        for bump in bumps {
            assert!(
                bump.get("package").is_some(),
                "each bump must have a package field; bump: {bump}"
            );
            assert!(
                bump.get("from").is_some(),
                "each bump must have a from field; bump: {bump}"
            );
            assert!(bump.get("to").is_some(), "each bump must have a to field; bump: {bump}");
            assert!(
                bump.get("severity").is_some(),
                "each bump must have a severity field; bump: {bump}"
            );
        }
    }

    /// A tagged `auto` package with a `feat:` commit after the tag and no changeset.
    fn auto_package_with_a_feat_commit(root: &std::path::Path) {
        git_init_with_commit(root);
        std::fs::write(
            root.join("Cargo.toml"),
            "[package]\nname = \"pkg-alpha\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::write(
            root.join("callisto.toml"),
            "[[package]]\nmatch = \"cargo/pkg-alpha\"\nrelease-trigger = \"auto\"\n",
        )
        .unwrap();
        run_git(root, &["add", "."]);
        run_git(root, &["commit", "-q", "-m", "chore: add package"]);
        run_git(
            root,
            &["-c", "tag.gpgSign=false", "tag", "-m", "release", "pkg-alpha@1.0.0"],
        );

        // A feat commit after the tag with no changeset: the only bump source is commit inference, whose pathspecs
        // are scoped to the package source dir (the workspace root here), so touching Cargo.toml counts.
        std::fs::write(
            root.join("Cargo.toml"),
            "[package]\nname = \"pkg-alpha\"\nversion = \"1.0.0\"\nedition = \"2021\"\n\
             description = \"a new feature\"\n",
        )
        .unwrap();
        run_git(root, &["add", "."]);
        run_git(root, &["commit", "-q", "-m", "feat: add a new feature"]);
    }

    /// A `release-trigger = "auto"` package with a `feat:` commit and no changeset gets an
    /// inferred minor bump through `select_inference()`, the call `handle()` makes.
    #[test]
    fn version_uses_real_commit_inference_for_auto_trigger() {
        use crate::runner::CliCommandRunner;
        use callisto_graph::locate::IgnoreWalkLocator;
        use callisto_model::BumpReason;

        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        auto_package_with_a_feat_commit(root);

        let locator = IgnoreWalkLocator::new(root);
        let runner = CliCommandRunner;
        let ws = callisto_graph::Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let inference = crate::workspace::select_inference();
        let opts = VersionOptions {
            strict: false,
            allow_empty_changesets: true,
        };

        let plan = plan_version(&ws, &inference, &opts).expect("plan_version must succeed");

        let pkg_alpha = PackageId::parse("pkg-alpha").unwrap();
        let bump = plan
            .bumps
            .iter()
            .find(|b| b.package == pkg_alpha)
            .expect("pkg-alpha must have a planned bump from commit inference");

        assert_eq!(bump.to.render(), "1.1.0", "a `feat:` commit must infer a minor bump");
        assert!(
            matches!(bump.reason, Some(BumpReason::Inference { .. })),
            "the bump must be attributed to inference, not a changeset (there is none); got: \
             {:?}",
            bump.reason
        );
    }

    /// The release pull request reads changesets only, so `status` warns about an inferred release with none.
    #[test]
    fn status_warns_about_an_inferred_release_that_has_no_changeset() {
        use crate::runner::CliCommandRunner;
        use callisto_graph::locate::IgnoreWalkLocator;
        use callisto_model::DiagnosticCode;

        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        auto_package_with_a_feat_commit(root);
        let status_codes = |root: &std::path::Path| {
            let locator = IgnoreWalkLocator::new(root);
            let runner = CliCommandRunner;
            let ws = callisto_graph::Workspace::load(root.to_path_buf(), &locator, &runner).unwrap();
            let inference = crate::workspace::select_inference();
            callisto_graph::commands::status(&ws, &inference, &callisto_graph::commands::StatusOptions::default())
                .unwrap()
                .diagnostics
                .into_iter()
                .map(|d| d.code)
                .collect::<Vec<_>>()
        };
        assert!(status_codes(root).contains(&DiagnosticCode::InferredReleaseWithoutChangeset));

        std::fs::create_dir_all(root.join(".changeset")).unwrap();
        std::fs::write(
            root.join(".changeset/new-feature.md"),
            "---\ncargo/pkg-alpha: minor\n---\n\nA new feature.\n",
        )
        .unwrap();
        assert!(!status_codes(root).contains(&DiagnosticCode::InferredReleaseWithoutChangeset));
    }

    /// `callisto version --dry-run --format text` must print the `[DRY-RUN]`
    /// marker and not modify any manifest on disk.
    #[test]
    fn handle_dry_run_text_output_carries_the_dry_run_marker_and_writes_nothing() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        make_fixture(root);
        std::fs::write(
            root.join("Cargo.toml"),
            "[workspace]\nmembers = [\"pkg-alpha\"]\nresolver = \"2\"\n",
        )
        .unwrap();
        std::fs::write(root.join("callisto.toml"), "").unwrap();

        let global = crate::cli::GlobalArgs {
            format: crate::cli::OutputFormat::Text,
            cwd: root.to_path_buf(),
            dry_run: true,
        };

        let manifest_before = std::fs::read_to_string(root.join("pkg-alpha/Cargo.toml")).unwrap();

        let args = crate::cli::VersionArgs {
            strict: false,
            allow_empty_changesets: true,
            refresh_lockfiles: false,
            no_refresh_lockfiles: true,
            emit_decision: None,
            emit_preview: None,
            abort: false,
        };
        let result = super::handle(args, &global);
        assert!(result.is_ok(), "expected Ok, got: {result:?}");

        let manifest_after = std::fs::read_to_string(root.join("pkg-alpha/Cargo.toml")).unwrap();
        assert_eq!(
            manifest_before, manifest_after,
            "dry-run must not modify pkg-alpha's Cargo.toml"
        );
    }
}

